function createFiber(tag, type, props = {}) {
  return {
    tag, // e.g. 'HostComponent', 'FunctionComponent'
    type, // 'div', 'span', or Component function
    pendingProps: props,
    memoizedProps: null,
    memoizedState: null,
    child: null,
    sibling: null,
    return: null,
    alternate: null
  };
}
